insert into f.perfil_operacao_evidencia (
  tenant_id, empresa_id, fonte, fonte_linha, natureza_texto, cfop,
  origem, cst_completo, cst_icms, aliquota_icms_observada,
  aliquota_ipi_observada, base_reduzida_observada, itens_observados,
  notas_observadas, ncms, notas_exemplo, leitura_operacional, faixa,
  justificativa_faixa, divergencia_ipi, divergencia_fabricado_revenda,
  divergencia_cabo_beneficio
)
select e.tenant_id, e.id, 'regras-nfe-63-combinacoes.csv', d.linha,
  d.natureza, d.cfop, d.origem, d.cst_completo, d.cst_icms,
  d.aliquota_icms, d.aliquota_ipi, d.base_reduzida, d.itens,
  d.notas, d.ncms, d.exemplos, d.leitura, d.faixa,
  d.justificativa, d.div_ipi, d.div_fabricado, d.div_cabo
from dados d
cross join c.empresa e
where e.codigo = 'SEG'
  and e.ativo is true
  and e.deleted_at is null;

insert into f.perfil_operacao (
  tenant_id, empresa_id, codigo, nome, modelo, natureza_operacao,
  natureza_texto, crt, cfop_interno, cfop_externo, cst_icms,
  cbenef, reducao_base_icms_percentual, beneficio_texto_legal,
  exige_referencia, exige_motivo, observacao, evidencia_id,
  faixa_automacao, justificativa_faixa, origem_mercadoria,
  aliquota_icms, aliquota_ipi, percentual_base_calculo,
  informacoes_complementares_modelo, habilitado_producao
)
select ev.tenant_id, ev.empresa_id,
  'CSV63-' || lpad(ev.fonte_linha::text, 3, '0'),
  ev.natureza_texto || ' | CFOP ' || ev.cfop || ' | origem ' || ev.origem || ' | CST ' || ev.cst_icms,
  'NFE', 'MATRIZ_CSV63_' || lpad(ev.fonte_linha::text, 3, '0'),
  ev.natureza_texto, '3',
  case when left(ev.cfop, 1) in ('1', '5') then ev.cfop end,
  case when left(ev.cfop, 1) in ('2', '6') then ev.cfop end,
  ev.cst_icms,
  case when ev.base_reduzida_observada then 'SC820006' end,
  case when ev.base_reduzida_observada then 29.4120 end,
  case when ev.base_reduzida_observada then
    'BASE DE CALCULO REDUZIDA - PRODUTOS DA INDUSTRIA DE AUTOMACAO, INFORMATICA E TELECOMUNICACOES, CONFORME DISPOE A ALINEA A DO ARTIGO 7, INCISO VII DO ANEXO 2 DO RICMS/SC.'
  end,
  ev.natureza_texto like '%RETORNO%'
    or ev.natureza_texto like '%REMESSA%'
    or ev.natureza_texto like '%ESTORNO%'
    or ev.natureza_texto like '%DEVOLUCAO%',
  ev.natureza_texto like '%OUTRA%'
    or ev.natureza_texto like '%OUTRAS%'
    or ev.natureza_texto like '999 - %'
    or ev.natureza_texto like '%DESTRUICAO%',
  'Perfil empírico da linha ' || ev.fonte_linha || ' do CSV; alíquota de IPI não parametrizada.',
  ev.id, ev.faixa, ev.justificativa_faixa, ev.origem,
  ev.aliquota_icms_observada, null,
  case when ev.base_reduzida_observada then 70.5880 end,
  case when ev.natureza_texto like '%INDUSTRIAL%' then
    'INDUSTRIALIZACAO POR ENCOMENDA. REFERENCIA LEGAL: REGULAMENTO DO IPI (RIPI/2010), APROVADO PELO DECRETO 7.212/2010. REDACAO FINAL PENDENTE DE VALIDACAO ANTES DA PRIMEIRA NOTA REAL.'
  end,
  false
from f.perfil_operacao_evidencia ev
where ev.fonte = 'regras-nfe-63-combinacoes.csv'
  and not exists (
    select 1 from f.perfil_operacao po where po.evidencia_id = ev.id
  );

update f.perfil_operacao_evidencia ev
set perfil_operacao_id = po.id
from f.perfil_operacao po
where po.evidencia_id = ev.id
  and ev.fonte = 'regras-nfe-63-combinacoes.csv';

commit;
